contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint newVal) public {
        // Set a log file first so we can observe it stays unchanged after init.
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        // Read the current log getter via Acc? No - Log is not public.
        // Use Initialize then attempt SetLogFile.
        c.Initialized(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetLogFile(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted && newVal >= 0);
    }
    receive() external payable {}
}

