// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 newVal) internal {
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetLogFile(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && newVal >= 0);
    }

    function testFuzz_run(uint256 newVal) public {
        _run(newVal);
    }

    receive() external payable {}
}
